ck & whiteinclude kDefaultRsrcName  'ics#' (kStationeryID);	// MacApp Stationery small black & whiteinclude kDefaultRsrcName  'ics4' (kApplicationID);	// MacApp Family small 4 bitinclude kDefaultRsrcName  'ics4' (kDocumentID);		// MacApp Document small 4 bitinclude kDefaultRsrcName  'ics4' (kStationeryID);	// MacApp Stationery small 4 bitinclude kDefaultRsrcName  'ics8' (kApplicationID);	// MacApp Family small 4 bitinclude kDefaultRsrcName  'ics8' (kDocumentID);		// MacApp Document small 4 bitinclude kDefaultRsrcName  'ics8' (kStationeryID);	// MacApp Stationery small 4 bitinclude kDefaultRsrcName  'icl4' (kApplicationID);	// MacApp Family large 4 bitinclude kDefaultRsrcName  'icl4' (kDocumentID);		// MacApp Document large 4 bitinclude kDefaultRsrcName  'icl4' (kStationeryID);	// MacApp Stationery large 4 bitinclude kDefaultRsrcName  'icl8' (kApplicationID);	// MacApp Family large 8 bitinclude kDefaultRsrcName  'icl8' (kDocumentID);		// MacApp Document large 8 bitinclude kDefaultRsrcName  'icl8' (kStationeryID);	// MacApp Stationery large 8 bit//--------------------------------------------------------------------------------------------------// Memory usage information for GrayscaleAppearance//--------------------------------------------------------------------------------------------------// See UMemory.h// -------------// Code fragment resource for PowerPC native apps// ----------------------------------------------#ifndef MW_Rez	// MW supplies it's own cfrg#if qPowerPC#include "CodeFragmentTypes.r"resource 'cfrg' (0, "Configuration Info") {	{		kPowerPC,		kFullLib,		kNoVersionNum,		kNoVersionNum,		0,		0,		kIsApp,		kOnDiskFlat,		kZeroOffset,		kWholeFork,		"GrayscaleAppearance"	}};#endif#endif	// MW_Rez//--------------------------------------------------------------------------------------------------// Icons, Bundles and FRefs… Oh my! (don't forget the Signature)//--------------------------------------------------------------------------------------------------type kSignature as 'STR ';resource kSignature (0,#if qNames"Signature",#endif	purgeable) {	"GrayscaleAppearance, "APPLE_LONG_COPYRIGHT};resource 'FREF' (kApplicationID,#if qNames"GrayscaleAppearance Application",#endif	purgeable) {	'APPL',	0,	""};resource 'FREF' (kDocumentID,#if qNames"GrayscaleAppearance Document",#endif	purgeable) {	kFileType,	1,	""};resource 'FREF' (kStationeryID,#if qNames"GrayscaleAppearance Stationery",#endif	purgeable) {	kStationery,	2,	""};resource 'BNDL' (kBundleID,#if qNames"GrayscaleAppearance",#endif	purgeable) {	kSignature,	0,	{ /* array TypeArray: 2 elements */		/* [1] */		'ICN#',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		},		/* [2] */		'FREF',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		}	}};//--------------------------------------------------------------------------------------------------//  Version resources//--------------------------------------------------------------------------------------------------// The revision of this particular fileRESOURCE 'vers' (1,#if qNames"File Version",#endif	purgeable) {	0x01,	0x00,	development,	0x00,	verUs,	"1.0",	"GrayscaleAppearance 1.0, "APPLE_LONG_COPYRIGHT};include kDefaultRsrcName  'vers' (2);		// Overall package//--------------------------------------------------------------------------------------------------//  String resources//--------------------------------------------------------------------------------------------------resource 'STR#' (kExtraStringBase, "kExtraStringBase", purgeable)	{{	"OK",	}};resource 'STR#' (kExtraStringBase + kSliderLabels1, "kSliderLabels1", purgeable)	{{	"Left Channel",	"Stereo",	"Right Channel",	}};resource 'STR#' (kExtraStringBase + kSliderLabels2, "kSliderLabels2", purgeable)	{{	"John",	"Paul",	"George",